[5632] = { en = "Returning Home", tier = 1,
  t = "Terug naar huis",
  d = "O, ja, natuurlijk. Hallo, $N. Niet lang geleden was hier een boodschapper van onze orde. Ze zocht jou. Ze zei dat er iets belangrijks gebeurt in Darnassus. Je moet zo snel als je kunt terug naar de Temple of the Moon. Praat daar met Priestess Alathea. Ik denk dat het te maken heeft met je goede vooruitgang in onze wegen.$B$BDus nog een keer: ga terug naar Darnassus als je kunt.",
  o = "Praat met Priestess Alathea in Darnassus.",
