[5633] = { en = "Returning Home", tier = 1,
  t = "Terug naar huis",
  d = "Gegroet, $gjongen:meid;. Fijn om je hier te zien in onze grote zalen. Een zegen voor jou en jouw volk.$B$BToen jij door ons land reisde, kwam hier een priesteres van jouw tempel. Ze zocht jou. Ze zei dat je zo snel mogelijk terug moest naar de Temple of the Moon. Sorry, ik kan je niet meer vertellen. Maar het klonk wel belangrijk. Als je bij de tempel bent, praat dan met Priestess Alathea.",
  o = "Praat met Priestess Alathea in Darnassus.",
  c = "Fijn, je bent weer thuis, $n. Tyrande en ik zijn altijd blij als onze leerlingen de wereld in gaan en veilig bij ons terugkomen. Hoe gaat het met je? Zegent Elune nog steeds je reizen? Misschien kun je me later meer over je reizen vertellen, als we eerst over het werk van vandaag hebben gepraat.",
  g = { {"Gegroet", "greetings"}, {"zalen", "halls (zaal)"}, {"zegen", "blessing"}, {"reisde", "traveled (reizen)"}, {"tempel", "temple"}, {"klonk", "sounded (klinken)"}, {"leerlingen", "students (leerling)"}, {"veilig", "safely, safe"}, {"terugkomen", "to come back"}, {"Zegent", "blesses (zegenen)"}, {"reizen", "travels, journeys (de reis)"} },
},

[5634] = { en = "Desperate Prayer", tier = 1,
  t = "Wanhopig gebed",
  c = "Je hebt het Licht goed gediend. Je bent een stralend voorbeeld voor iedereen die door deze gevaarlijke landen reist, en verder. Neem alsjeblieft deze les aan als dank voor alles wat je hebt gedaan.",
  g = { {"Wanhopig", "desperate"}, {"gebed", "prayer"}, {"gediend", "served (dienen)"}, {"stralend", "shining (stralen)"}, {"voorbeeld", "example"}, {"gevaarlijke", "dangerous (gevaarlijk)"}, {"Neem", "take (nemen; aannemen = to accept)"} },
},

[5635] = { en = "Desperate Prayer", tier = 1,
  t = "Wanhopig gebed",
  d = "Onze leiders hebben je opgemerkt, $N. Ze vragen je om zo snel mogelijk naar de Cathedral of Light in Stormwind te gaan. Blijkbaar vinden ze dat je jezelf al hebt bewezen. Je bent klaar voor meer training. Zoek daar High Priestess Laurena. Zij kan je verder helpen. Succes, en moge het Licht met je zijn.",
  o = "Praat met High Priestess Laurena in Stormwind.",
  c = "Fijn dat je er bent, $n. We moeten veel dingen bespreken. Maar je training in de wegen van het Licht is belangrijker.$b$bEr zijn lessen die alle dienaren van het Licht moeten leren. Als je klaar bent, beginnen we nu met een paar van die lessen.",
  g = { {"Wanhopig", "desperate"}, {"gebed", "prayer"}, {"leiders", "leaders (leider)"}, {"opgemerkt", "noticed (opmerken)"}, {"Blijkbaar", "apparently"}, {"bewezen", "proven (bewijzen)"}, {"bespreken", "to discuss"}, {"wegen", "ways (de weg)"}, {"dienaren", "servants (dienaar)"}, {"lessen", "lessons (les)"} },
},

[5636] = { en = "Desperate Prayer", tier = 1,
  t = "Wanhopig gebed",
  d = "Elune zegene je, beste $r. Ik hoop dat jouw Licht je vandaag vindt en goed beschermt.$B$BNiet lang geleden was hier een van jullie priesters. Hij zocht jou. Hij zei dat je zo snel mogelijk terug moet naar de Cathedral of Light. Daar moet je met High Priestess Laurena praten. Je hebt het blijkbaar goed gedaan, als je zoveel aandacht krijgt. Blijf hier niet te lang. Je volk heeft je nodig.",
